/**
 * Generates the byte-identity fixture for SP2, from the resolver AS IT IS
 * BEFORE the theme dimension exists.
 *
 * Run once, with the pre-change resolver, and committed. The pin that follows
 * compares the post-change no-theme output against this file, so the fixture
 * must never be regenerated by the code it is meant to hold still - that is
 * how a pin quietly becomes a snapshot of the bug.
 *
 *   npx tsx dev-scripts/generate-search-locations-fixture.ts
 *
 * It lives OUTSIDE the test glob on purpose: a generator that runs in CI
 * rewrites the pin with whatever the code currently does, which is how a pin
 * quietly becomes a snapshot of the bug it was meant to catch.
 */
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { screenSearchLocations } from '../src/screens/screen-resolution';

const SCREENS = ['LOGON', 'BULL', 'MENU', 'CONF_BULL', 'GOODBYE', 'NODE_BULL', 'AWAITSCREEN'];
const CASES = [
  { nodeId: 1, confId: 1 },
  { nodeId: 7, confId: 2 },
  { nodeId: 0, confId: undefined },
];

function generate(): void {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'locations-fixture-'));
  // A board shaped like the real one: conferences whose directories come from
  // ConfConfig.info, not from their numbers.
  fs.writeFileSync(path.join(root, 'ConfConfig.info'), '');

  const rows: Record<string, unknown> = {};
  for (const screen of SCREENS) {
    for (const opts of CASES) {
      const key = `${screen}|node=${opts.nodeId}|conf=${opts.confId ?? '-'}`;
      rows[key] = screenSearchLocations(root, screen, opts).map(location => ({
        dir: location.dir.replace(root, '<root>'),
        desc: location.desc,
      }));
    }
  }

  fs.writeFileSync(
    path.join(__dirname, '..', 'tests', 'screens', 'fixtures', 'search-locations.json'),
    JSON.stringify(rows, null, 2) + '\n'
  );
  fs.rmSync(root, { recursive: true, force: true });
}

generate();
